  if (relative_parsed.password.is_valid)
    replacements.SetPassword(base_url + relative_parsed.password, url_parse::REPLACE);
  if (relative_parsed.host.is_valid)
    replacements.SetHost(base_url + relative_parsed.host, url_parse::REPLACE);
  if (relative_parsed.port.is_valid)
    replacements.SetPort(base_url + relative_parsed.port, url_parse::REPLACE);
